package com.motionstudio.part3
import kotlin.math.*
import com.motionstudio.part2.*
data class GradientStop(val position:Float,val color:Rgba)
sealed interface Shape{data class Rect(val w:Float,val h:Float):Shape;data class Ellipse(val rx:Float,val ry:Float):Shape;data class Polygon(val points:List<Point2>):Shape;data class Star(val points:Int,val inner:Float,val outer:Float):Shape;data class Path(val points:List<Point2>,val closed:Boolean):Shape}
data class ShapeStyle(val fill:Rgba=Rgba.WHITE,val stroke:Rgba=Rgba.TRANSPARENT,val strokeWidth:Float=0f,val gradient:List<GradientStop> = emptyList(),val trimStart:Float=0f,val trimEnd:Float=1f)
object ShapeEngine{fun rasterize(shape:Shape,style:ShapeStyle,width:Int,height:Int):FrameBuffer{val o=FrameBuffer(width,height);for(y in 0 until height)for(x in 0 until width){val inside=contains(shape,x+.5f,y+.5f);if(inside)o.set(x,y,style.fill)};return o};private fun contains(s:Shape,x:Float,y:Float)=when(s){is Shape.Rect->x>=0&&y>=0&&x<=s.w&&y<=s.h;is Shape.Ellipse->(x/s.rx).pow(2)+(y/s.ry).pow(2)<=1;is Shape.Polygon->poly(s.points,x,y);is Shape.Star->poly(star(s),x,y);is Shape.Path->poly(s.points,x,y)};private fun poly(p:List<Point2>,x:Float,y:Float):Boolean{if(p.size<3)return false;var c=false;var j=p.lastIndex;for(i in p.indices){if((p[i].y>y)!=(p[j].y>y)&&x<(p[j].x-p[i].x)*(y-p[i].y)/(p[j].y-p[i].y)+p[i].x)c=!c;j=i};return c};private fun star(s:Shape.Star):List<Point2>{val n=s.points.coerceAtLeast(2)*2;return (0 until n).map{val r=if(it%2==0)s.outer else s.inner;val a=-Math.PI/2+it*Math.PI/s.points;Point2(cos(a).toFloat()*r,sin(a).toFloat()*r)}}}
